package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=db.internal port=5432 user=app_user dbname=inventory sslmode=require")
	if err != nil {
		log.Fatal(err)
	}
}

// SearchHandler allows warehouse staff to search inventory by product attributes
func SearchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	warehouse := r.URL.Query().Get("warehouse")
	minQty := r.URL.Query().Get("min_qty")

	if category == "" {
		http.Error(w, "category is required", 400)
		return
	}

	// Build dynamic query based on filters
	var conditions []string
	conditions = append(conditions, fmt.Sprintf("category = '%s'", category))

	if warehouse != "" {
		conditions = append(conditions, fmt.Sprintf("warehouse_id = '%s'", warehouse))
	}

	if minQty != "" {
		conditions = append(conditions, fmt.Sprintf("quantity >= %s", minQty))
	}

	query := fmt.Sprintf("SELECT product_id, name, quantity, warehouse_id FROM inventory WHERE %s ORDER BY name LIMIT 100",
		strings.Join(conditions, " AND "))

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	for rows.Next() {
		var productID, name, warehouseID string
		var quantity int
		if err := rows.Scan(&productID, &name, &quantity, &warehouseID); err != nil {
			continue
		}
		fmt.Fprintf(w, "%s | %s | %d | %s\n", productID, name, quantity, warehouseID)
	}
}

// BulkUpdateHandler processes CSV-style bulk quantity updates
func BulkUpdateHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	lines := strings.Split(r.FormValue("updates"), "\n")
	tx, err := db.Begin()
	if err != nil {
		http.Error(w, "Transaction error", 500)
		return
	}

	for _, line := range lines {
		parts := strings.Split(strings.TrimSpace(line), ",")
		if len(parts) != 2 {
			continue
		}
		productID := parts[0]
		newQty := parts[1]

		updateSQL := fmt.Sprintf("UPDATE inventory SET quantity = %s, updated_at = NOW() WHERE product_id = '%s'",
			newQty, productID)
		_, err := tx.Exec(updateSQL)
		if err != nil {
			tx.Rollback()
			http.Error(w, fmt.Sprintf("Update failed: %v", err), 500)
			return
		}
	}

	if err := tx.Commit(); err != nil {
		http.Error(w, "Commit failed", 500)
		return
	}
	fmt.Fprintf(w, "Updated %d records", len(lines))
}

func main() {
	http.HandleFunc("/api/v2/inventory/search", SearchHandler)
	http.HandleFunc("/api/v2/inventory/bulk-update", BulkUpdateHandler)
	log.Println("Inventory service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
